#[test]
fn unit_metadata() {
    let info = Acceleration::<f64>::INFO;
    assert_eq!(info.name, "Acceleration");
    assert_eq!(info.units.len(), AccelerationUnit::ALL.len());
    for (&unit, unit_info) in AccelerationUnit::ALL.iter().zip(info.units) {
        assert_eq!(unit.info(), unit_info);
        assert_eq!(format!("{unit:?}"), unit_info.singular);
        assert_eq!(unit.abbreviation(), unit_info.abbreviation);
        assert_eq!(unit.all_abbreviations(), unit_info.abbreviations);
    }
    assert_eq!(
        info.base_unit,
        AccelerationUnit::MeterPerSecondSquared.info()
    );
}

#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::MeterPerSecondSquared),
        Acceleration::from_meters_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::MeterPerSecondSquared),
        Acceleration::from_base(v).as_meters_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::NanometerPerSecondSquared),
        Acceleration::from_nanometers_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::NanometerPerSecondSquared),
        Acceleration::from_base(v).as_nanometers_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::MicrometerPerSecondSquared),
        Acceleration::from_micrometers_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::MicrometerPerSecondSquared),
        Acceleration::from_base(v).as_micrometers_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::MillimeterPerSecondSquared),
        Acceleration::from_millimeters_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::MillimeterPerSecondSquared),
        Acceleration::from_base(v).as_millimeters_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::CentimeterPerSecondSquared),
        Acceleration::from_centimeters_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::CentimeterPerSecondSquared),
        Acceleration::from_base(v).as_centimeters_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::DecimeterPerSecondSquared),
        Acceleration::from_decimeters_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::DecimeterPerSecondSquared),
        Acceleration::from_base(v).as_decimeters_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::KilometerPerSecondSquared),
        Acceleration::from_kilometers_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::KilometerPerSecondSquared),
        Acceleration::from_base(v).as_kilometers_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::InchPerSecondSquared),
        Acceleration::from_inches_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::InchPerSecondSquared),
        Acceleration::from_base(v).as_inches_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::FootPerSecondSquared),
        Acceleration::from_feet_per_second_squared(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::FootPerSecondSquared),
        Acceleration::from_base(v).as_feet_per_second_squared()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::KnotPerSecond),
        Acceleration::from_knots_per_second(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::KnotPerSecond),
        Acceleration::from_base(v).as_knots_per_second()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::KnotPerMinute),
        Acceleration::from_knots_per_minute(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::KnotPerMinute),
        Acceleration::from_base(v).as_knots_per_minute()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::KnotPerHour),
        Acceleration::from_knots_per_hour(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::KnotPerHour),
        Acceleration::from_base(v).as_knots_per_hour()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::StandardGravity),
        Acceleration::from_standard_gravity(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::StandardGravity),
        Acceleration::from_base(v).as_standard_gravity()
    );
    assert_eq!(
        Acceleration::new(v, AccelerationUnit::MillistandardGravity),
        Acceleration::from_millistandard_gravity(v)
    );
    assert_eq!(
        Acceleration::from_base(v).convert_to(AccelerationUnit::MillistandardGravity),
        Acceleration::from_base(v).as_millistandard_gravity()
    );
}

